        "factor": "Bipartisan support and external advocacy",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Broad backing increases pressure for Senate consideration; still insufficient without final Senate action."
      },
      {
        "factor": "Ongoing U.S.-Taiwan negotiations / enabling legislation",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Progress toward a bilateral tax framework could facilitate implementing legislation; dependent on outcomes."
      },
      {
        "factor": "Historic enactment rate for federal legislation",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Long-run historical odds of passage are low for measures requiring two chambers and presidential signature."
      }
